(7215052, 1112164, 114225, '<td valign="top">Overall fits the theme fine, but I find it to be a bit too crowded. Maybe focus more on certain aspects.</td>', 'Overall fits the theme fine, but I find it to be a bit too crowded. Maybe focus more on certain aspects.', '2014-05-09 10:58:03.000000', NULL, 1),
(7215054, 1112175, 114225, '<td valign="top">Overall, the image was fine, but something was bothering me. Upon further look, I think it''s too out of balance to the left, at least with just part of the bottle showing. Show the full bottle, and I think the composition works more.</td>', 'Overall, the image was fine, but something was bothering me. Upon further look, I think it''s too out of balance to the left, at least with just part of the bottle showing. Show the full bottle, and I think the composition works more.', '2014-05-09 10:59:47.000000', NULL, 1),
(7215055, 1112210, 114225, '<td valign="top">Funny that you picked the least authentic part of the Mexican food aisle (At least I assume so, based on my local grocery stores).</td>', 'Funny that you picked the least authentic part of the Mexican food aisle (At least I assume so, based on my local grocery stores).', '2014-05-09 11:00:35.000000', NULL, 1),
(7215056, 1112208, 114225, '<td valign="top">To me, this is just a random snapshot of a building. This building has so much character, but you didn''t use it to your advantage.</td>', 'To me, this is just a random snapshot of a building. This building has so much character, but you didn''t use it to your advantage.', '2014-05-09 11:00:37.000000', NULL, 1),
